const test=require('node:test'),assert=require('node:assert/strict');
async function fixture(armed=false){const {syncEncounter}=await import('../outbreak-simulation.mjs');const graph={nodes:{'z#0':{x:0,y:0,z:0},'z#1':{x:10,y:0,z:0},'p#0':{x:20,y:0,z:0},'p#1':{x:30,y:0,z:0}},adj:{'z#0':[{id:'z#1',cost:10}],'z#1':[{id:'z#0',cost:10},{id:'p#0',cost:10}],'p#0':[{id:'z#1',cost:10},{id:'p#1',cost:10}],'p#1':[{id:'p#0',cost:10}]},hubs:{z:'z#0',p:'p#0'},signature:'connected'};const board={instances:[{instanceId:'z',cardId:'z',cardRevision:1},{instanceId:'p',cardId:'p',cardRevision:1}],cards:{'z@1':{recipe:{seed:41,agents:{archetype:'zombie',count:3}}},'p@1':{recipe:{seed:63,agents:{archetype:armed?'broom-elder':'person',count:3}}}}};const world={id:'fixture',seconds:0,entities:{'place/z':{id:'place/z',active:true,hub:'z'},'place/p':{id:'place/p',active:true,hub:'p'}},groups:{}};return {world:syncEncounter(world,board,graph),graph,board};}
test('Unarmed people actually flee and zombies catch and eat them on shared paths',async()=>{const {advanceEncounter,encounterReport}=await import('../outbreak-simulation.mjs'),{world,graph}=await fixture();let w=advanceEncounter(world,graph,1);assert(Object.values(w.actors).some(a=>a.intent==='fleeing'));assert(Object.values(w.actors).some(a=>a.intent==='chasing'));w=advanceEncounter(w,graph,150);const r=encounterReport(w);assert.equal(r.people,0);assert.equal(r.eaten,3);assert.equal(r.zombies,3);assert(Object.values(w.actors).every(a=>a.metres>0));});
test('Disconnected nearby tiles cannot exchange attacks or actors',async()=>{const {advanceEncounter,encounterReport}=await import('../outbreak-simulation.mjs'),{world,graph}=await fixture();graph.adj['z#1']=graph.adj['z#1'].filter(e=>e.id!=='p#0');graph.adj['p#0']=graph.adj['p#0'].filter(e=>e.id!=='z#1');graph.signature='broken';const w=advanceEncounter(world,graph,120);assert.equal(encounterReport(w).eaten,0);assert.equal(w.encounter.hits,0);assert(Object.values(w.actors).filter(a=>a.team==='undead').every(a=>a.position.x<=10));});
test('Brooms grant real attacks, health damage and zombie defeats',async()=>{const {advanceEncounter,encounterReport}=await import('../outbreak-simulation.mjs'),{world,graph}=await fixture(true);const w=advanceEncounter(world,graph,150),r=encounterReport(w);assert(w.encounter.hits>0);assert(r.defeated>0);assert(Object.values(w.actors).some(a=>a.team==='undead'&&a.hp<4));});
test('Simulation is repeatable across step batches and save reload, with no resurrection',async()=>{const {advanceEncounter}=await import('../outbreak-simulation.mjs'),{world,graph}=await fixture(true);let a=advanceEncounter(world,graph,20);a=advanceEncounter(JSON.parse(JSON.stringify(a)),graph,40);assert.deepEqual(a,advanceEncounter(world,graph,60));const dead=Object.values(a.actors).filter(a=>a.hp<=0).map(a=>a.id);a=advanceEncounter(a,graph,30);assert(dead.every(id=>a.actors[id].hp===0));});
test('Boost/equipment changes capabilities; spawns create new identities and a bounded population',async()=>{const {equipPeople,strengthen,spawnActors}=await import('../outbreak-simulation.mjs'),{world,graph,board}=await fixture();let w=equipPeople(world);assert(Object.values(w.actors).filter(a=>a.team==='living').every(a=>a.weapon==='broom'));w=strengthen(w,'living');assert(Object.values(w.actors).filter(a=>a.team==='living').every(a=>a.hp===7&&a.damageBonus===1));const before=new Set(Object.keys(w.actors));w=spawnActors(w,board,graph,'z',4);assert.equal(Object.keys(w.actors).length,before.size+4);assert.throws(()=>spawnActors(w,board,graph,'z',100),/1–32/);});
test('Real generated hexes certify connected terrain paths and resolve the unarmed encounter',async()=>{const {advanceEncounter,encounterReport}=await import('../outbreak-simulation.mjs'),{world,graph,economy}=await require('./outbreak-fixture.cjs')();assert.equal(economy.model.connections.length,1);assert(Object.keys(graph.nodes).length>20);assert(graph.signature.length<64);const w=advanceEncounter(world,graph,600),r=encounterReport(w);assert.equal(r.people,0);assert.equal(r.eaten,3);assert(Object.values(w.actors).some(a=>a.metres>100));});
test('Removing a scene mid-chase archives its actors; restoring does not respawn or teleport them',async()=>{const {advanceEncounter,syncEncounter}=await import('../outbreak-simulation.mjs'),{world,graph,board}=await fixture();let w=advanceEncounter(world,graph,8);const before=structuredClone(w.actors),removed={...board,instances:board.instances.filter(i=>i.instanceId!=='p')};w=syncEncounter(w,removed,graph);w=advanceEncounter(w,graph,10);assert(Object.values(w.actors).filter(a=>a.team==='living').every(a=>!w.entities[a.id].active&&a.hp===before[a.id].hp));w=syncEncounter(w,board,graph);assert.equal(Object.keys(w.actors).length,6);assert(Object.values(w.actors).filter(a=>a.team==='living').every(a=>w.entities[a.id].active));for(const a of Object.values(w.actors).filter(a=>a.team==='living'))assert.deepEqual(a.position,before[a.id].position);});
test('An interrupted route and attack cannot hit across removed topology',async()=>{const {advanceEncounter}=await import('../outbreak-simulation.mjs'),{world,graph}=await fixture();let w=advanceEncounter(world,graph,12);const before=structuredClone(w.actors);const empty={nodes:{},adj:{},hubs:{},signature:'removed'};w=advanceEncounter(w,empty,10);for(const a of Object.values(w.actors)){assert.equal(a.hp,before[a.id].hp);assert.deepEqual(a.position,before[a.id].position);}});
test('Reload synchronization preserves an unchanged encounter decision schedule',async()=>{const {advanceEncounter,syncEncounter}=await import('../outbreak-simulation.mjs'),{world,graph,board}=await fixture(true);const halfway=advanceEncounter(world,graph,10.25),reloaded=syncEncounter(JSON.parse(JSON.stringify(halfway)),board,graph);assert.deepEqual(advanceEncounter(reloaded,graph,20),advanceEncounter(halfway,graph,20));});
test('Nearby actors on the same certified edge can close and strike without detouring to a junction',async()=>{const {advanceEncounter}=await import('../outbreak-simulation.mjs'),{world,graph}=await fixture();const actors=Object.values(world.actors),z=actors.find(a=>a.team==='undead'),p=actors.find(a=>a.team==='living');for(const a of actors)if(a!==z&&a!==p)a.hp=0;z.position={x:24,y:0,z:0};p.position={x:24.4,y:0,z:0};const next=advanceEncounter(world,graph,2);assert(next.actors[p.id].hp<5,'A reachable target in the middle of an edge must take damage');assert(next.actors[z.id].position.x>23);});
